export async function createLock(
  hre: HardhatRuntimeEnvironment,
  {
    name,
    keyPrice,
    expirationDuration,
    currencyContractAddress,
    maxNumberOfKeys,
    beneficiary,
    version = PUBLIC_LOCK_LATEST_VERSION,
    unlockAddress,
  }: CreateLockArgs
): Promise<{
  lock: Contract
  lockAddress: string
  transactionHash: string
}> {
  console.log(`Creating lock ${version}...`)

  // send tx
  const [signer] = await hre.ethers.getSigners()
  if (!beneficiary) beneficiary = signer.address

  // create call data
  const { abi } = getContractAbi('PublicLock', version)
  const iface = new Interface(abi)

  // encode initializer data
  const fragment = iface.getFunction(
    'initialize(address,uint256,address,uint256,uint256,string)'
  )
  const calldata = iface.encodeFunctionData(fragment, [
    beneficiary,
    expirationDuration,
    currencyContractAddress || ZeroAddress,
    keyPrice,
    maxNumberOfKeys,
    name,
  ])

  // create the lock
  const unlock = await getUnlockContract(hre, unlockAddress)
  const tx = await unlock.createUpgradeableLockAtVersion(calldata, version)
  const receipt = await tx.wait()
  const transactionHash = receipt.hash

  // parse the NewLock event from the transaction logs (ethers v6)
  let newLockAddress: string | undefined
  for (const log of receipt.logs) {
    try {
      const parsed = unlock.interface.parseLog(log)
      if (parsed && parsed.name === 'NewLock') {
        ;({ newLockAddress } = parsed.args)
        break
      }
    } catch (error) {
      // log does not belong to the Unlock contract, skip it
    }
  }

  const lock = await getLockContract(hre, newLockAddress as string)
  return {
    lock,
    lockAddress: await lock.getAddress(),
    transactionHash,
  }
}
